def backfill_channel(apps, schema_editor):
    """Tags existing movements with a channel where it's unambiguous.
    Only the new descriptive column is written — quantities, locations
    and dates of the ledger rows are untouched."""
    StockMovement = apps.get_model("owner_inventory", "StockMovement")
    rows = StockMovement.objects.filter(channel="")

    rows.filter(
        movement_type="RECEIVED", reference__startswith="Manufacturer order"
    ).update(channel="MANUFACTURER")
    rows.filter(movement_type="TRANSFER", to_location__location_type="TRANSIT").update(
        channel="DISTRIBUTOR"
    )
    rows.filter(movement_type="TRANSFER", from_location__location_type="TRANSIT").update(
        channel="DISTRIBUTOR"
    )
    # "Give to Distributor": straight out of an owned warehouse to nobody.
    rows.filter(
        movement_type="TRANSFER",
        from_location__location_type="OWN",
        to_location__isnull=True,
    ).update(channel="DISTRIBUTOR")
    rows.filter(
        movement_type="TRANSFER", from_location__location_type="UNALLOCATED"
    ).update(channel="INTERNAL")


